{
  "missing_information": [
    {
      "category": "Trigger Conditions",
      "gap": "No information on what initiates a sample transfer request (e.g., evaluation schedule, ad-hoc demand, automated signal from equipment)",
      "why_it_matters": "Understanding the trigger is essential to determine whether the initiation step can be automated or requires manual intervention"
    },
    {
      "category": "Roles and Responsibilities",
      "gap": "The actors involved in each step (who requests, who approves, who physically moves samples, who evaluates) are not defined",
      "why_it_matters": "Role clarity is required to map handoffs, identify bottlenecks, and assess which steps could be automated or reassigned"
    },
    {
      "category": "Evaluation Criteria",
      "gap": "No criteria are given for determining whether a sample is 'unnecessary' after evaluation",
      "why_it_matters": "Without defined criteria, the decision point for disposal cannot be modeled or automated reliably"
    },
    {
      "category": "Disposal Request Process",
      "gap": "The steps, approvals, and systems involved in the disposal request process are not described",
      "why_it_matters": "The disposal sub-process may involve regulatory compliance, safety checks, or multi-level approvals that significantly affect cycle time and automation potential"
    },
    {
      "category": "Systems and Data",
      "gap": "No information about the systems used to log, track, or manage sample transfers and disposal requests",
      "why_it_matters": "System integration points are critical for identifying where process data is captured and where automation tools could connect"
    },
    {
      "category": "Exception Handling",
      "gap": "No information on how exceptions are handled, such as damaged samples, failed evaluations, or rejected disposal requests",
      "why_it_matters": "Exception paths often represent the highest manual effort and are key targets for automation or standardization"
    }
  ],
  "clarification_questions": [
    {
      "id": "Q1",
      "question": "What event or condition triggers a wafer sample transfer request — for example, is it driven by a planned evaluation schedule, a manual request from an engineer, or an automated signal from a piece of equipment?",
      "targets": ["Trigger Conditions"]
    },
    {
      "id": "Q2",
      "question": "Which roles or teams are responsible for each major step in the process — specifically, who initiates the transfer, who approves it, who physically moves the sample, and who performs the evaluation?",
      "targets": ["Roles and Responsibilities"]
    },
    {
      "id": "Q3",
      "question": "What specific criteria or rules are used to decide that a sample is no longer needed after evaluation and should be flagged for disposal?",
      "targets": ["Evaluation Criteria"]
    },
    {
      "id": "Q4",
      "question": "Can you walk through the steps of the disposal request process — for instance, how is the request submitted, what approvals are required, and how is the physical disposal carried out and confirmed?",
      "targets": ["Disposal Request Process"]
    },
    {
      "id": "Q5",
      "question": "What systems or tools are used to record and track sample transfers and disposal requests throughout the workflow?",
      "targets": ["Systems and Data"]
    },
    {
      "id": "Q6",
      "question": "What happens when a disposal request is rejected or a sample is found to be damaged during transfer — is there a defined exception path, and who is responsible for resolving it?",
      "targets": ["Exception Handling"]
    }
  ]
}
